// Seed the exercise catalog from free-exercise-db (public domain).
//
// Every exercise gets a `measurement` and `progression` from rules.
// A curated subset also gets a `movement_pattern` + `priority`, which is what
// makes it reachable by the generator — everything else stays NULL and is
// loggable-but-never-generated by construction.
//
// Usage: node scripts/seed-exercises.mjs   (emits d1/seed.sql)

import { readFileSync, writeFileSync, existsSync } from 'fs';

const SRC = 'data/exercises.json';
const OUT = 'd1/seed.sql';
const DATA_URL =
	'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/dist/exercises.json';

if (!existsSync(SRC)) {
	const res = await fetch(DATA_URL);
	if (!res.ok) throw new Error(`download failed: ${res.status}`);
	writeFileSync(SRC, await res.text());
}

const exercises = JSON.parse(readFileSync(SRC, 'utf8'));

// ---------------------------------------------------------------------------
// Measurement + progression: rules over category / equipment / name.

const STATIC_HOLD = /plank|hold|l-sit|wall sit|iron cross/i;
const CARRY = /farmer|carry|suitcase|yoke walk|waiter/i;
const DISTANCE = /run|jog|sprint|cycl|bike|row(er|ing)|swim|walk|stair|elliptical|ski/i;

// Bodyweight compounds people commonly load two ways: an assisted machine or
// band (net load goes negative) once bodyweight reps are still out of reach,
// or a dip belt/vest (net load goes positive) once bodyweight reps are easy.
// These get `load_reps` instead of `reps_only` so the existing weight field
// and double-progression math carry the net number — 0 means bodyweight
// only. Deliberately a named list, not every 'body only' exercise: most of
// the catalog (planks, crunches, stretches) has no assisted/added practice.
const ASSIST_CAPABLE = new Set(['Pullups', 'Chin-Up', 'Dips - Triceps Version']);

function classify(e) {
	const name = e.name;
	const cat = e.category;
	const eq = e.equipment ?? 'none';
	if (cat === 'stretching') return { measurement: 'time', progression: 'none' };
	if (cat === 'cardio') {
		return DISTANCE.test(name)
			? { measurement: 'distance_time', progression: 'none' }
			: { measurement: 'time', progression: 'none' };
	}
	if (cat === 'plyometrics') return { measurement: 'reps_only', progression: 'none' };
	if (CARRY.test(name)) return { measurement: 'load_time', progression: 'time' };
	if (STATIC_HOLD.test(name)) return { measurement: 'time', progression: 'time' };
	if (ASSIST_CAPABLE.has(name)) return { measurement: 'load_reps', progression: 'double' };
	if (eq === 'body only') return { measurement: 'reps_only', progression: 'double' };
	return { measurement: 'load_reps', progression: 'double' };
}

// ---------------------------------------------------------------------------
// Movement patterns: ordered keyword rules, first match wins. Only strength-
// type categories are eligible; everything else keeps NULL.

const ELIGIBLE_CAT = new Set(['strength', 'powerlifting', 'strongman']);
const ELIGIBLE_EQ = new Set([
	'barbell', 'dumbbell', 'machine', 'cable', 'body only', 'e-z curl bar', 'kettlebells', 'other'
]);
// Specialty-implement variants never deserve a generator slot.
const EXCLUDE = /with chains|with bands|smith|band assisted|axle|car deadlift|guillotine|jm press|rack pull|sled|zercher|jefferson|frankenstein|kneeling squat|jerk/i;

const PATTERN_RULES = [
	[/upright row/i, null],
	[/wrist|finger/i, null],
	[/push-?up/i, 'horizontal_press'],
	[/incline.*(bench|press)|(bench|press).*incline/i, (e) => (has(e, 'chest') ? 'incline_press' : null)],
	[/bench press|chest press|floor press|decline.*press/i, 'horizontal_press'],
	[/close-grip.*bench/i, 'triceps_extension'],
	[/dip machine|dips/i, (e) => (has(e, 'chest') ? 'horizontal_press' : 'triceps_extension')],
	[/shoulder press|military press|overhead press|push press|arnold press/i, 'vertical_press'],
	[/pulldown|pull-?up|pullup|chin-?up|chinup/i, 'vertical_pull'],
	[/pullover/i, 'pullover'],
	[/face pull/i, 'rear_delt'],
	[/shrug/i, 'shrug'],
	[/row/i, 'horizontal_pull'],
	[/romanian|stiff-legged|stiff leg|straight-leg deadlift/i, 'hip_hinge'],
	[/deadlift/i, 'hip_hinge'],
	[/good morning/i, 'hip_hinge'],
	[/pull through/i, 'hip_hinge'],
	[/hyperextension|back extension/i, 'hip_hinge'],
	[/hip thrust|glute bridge/i, 'hip_thrust'],
	[/split squat|bulgarian/i, 'lunge'],
	[/leg press|hack squat/i, 'squat'],
	[/squat/i, (e) => (e.equipment === 'body only' ? null : 'squat')],
	[/lunge|step-up|step up/i, 'lunge'],
	[/leg extension/i, 'leg_extension'],
	[/leg curl/i, 'leg_curl'],
	[/calf|toe press/i, 'calf_raise'],
	[/flye?s?\b|pec deck|butterfly|cable crossover/i, (e) => (has(e, 'chest') ? 'chest_fly' : 'rear_delt')],
	[/lateral raise|side lateral/i, 'lateral_raise'],
	[/rear delt|reverse fl/i, 'rear_delt'],
	[/preacher|concentration|hammer curl|curl/i, (e) => (has(e, 'biceps') ? 'biceps_curl' : null)],
	[/pushdown|push-down|skullcrusher|french press|triceps? extension|kickback/i, 'triceps_extension'],
	[/cable crunch|crunch|sit-?up|leg raise|knee raise|russian twist|ab roller|rollout/i, 'ab_flexion'],
	[/plank/i, 'anti_extension'],
	[CARRY, 'loaded_carry']
];

function has(e, muscle) {
	return e.primaryMuscles.includes(muscle) || e.secondaryMuscles.includes(muscle);
}

function pattern(e) {
	if (!ELIGIBLE_CAT.has(e.category)) return null;
	if (!ELIGIBLE_EQ.has(e.equipment ?? '')) return null;
	if (EXCLUDE.test(e.name)) return null;
	for (const [re, p] of PATTERN_RULES) {
		if (re.test(e.name)) return typeof p === 'function' ? p(e) : p;
	}
	return null;
}

// Base priority: how likely the generator should be to pick it, before the
// curated overrides pin the classics to the top.
function basePriority(e, pat) {
	if (!pat) return 0;
	const eq = { barbell: 50, dumbbell: 45, machine: 40, cable: 38, 'e-z curl bar': 35, kettlebells: 28, 'body only': 26, other: 15 }[e.equipment ?? ''] ?? 10;
	const compound = e.mechanic === 'compound' ? 8 : 0;
	const simple = e.level === 'beginner' ? 4 : e.level === 'intermediate' ? 2 : 0;
	// Long names are almost always oddball variants
	const oddball = e.name.length > 32 ? -12 : 0;
	return eq + compound + simple + oddball;
}

// ---------------------------------------------------------------------------
// Curated overrides: the classics, pinned to the top of their pattern, with
// the aliases people actually use and short coaching cues.
// Names must match the dataset exactly — misses are reported loudly.

const OVERRIDES = {
	'Barbell Bench Press - Medium Grip': { priority: 100, aliases: ['Bench Press', 'Flat Barbell Bench Press', 'BB Bench'], cues: 'Shoulder blades pinned, slight arch. Bar to lower chest. Feet drive through the floor.' },
	'Dumbbell Bench Press': { priority: 95, aliases: ['DB Bench Press', 'Flat DB Press', 'Dumbbell Press'], cues: 'Elbows ~45° from torso. Press up and slightly in. Control the stretch at the bottom.' },
	'Barbell Incline Bench Press - Medium Grip': { priority: 95, aliases: ['Incline Bench Press', 'Incline Barbell Press'], cues: 'Bar touches just below the collarbone. Keep the elbows under the bar.' },
	'Incline Dumbbell Press': { priority: 96, aliases: ['Incline DB Press'], cues: '30–45° bench. Press up and slightly back. Deep stretch, no bounce.' },
	'Pushups': { priority: 70, aliases: ['Push-Up', 'Press-Up'], cues: 'Rigid plank from head to heels. Chest to floor, full lockout.' },
	'Barbell Shoulder Press': { priority: 95, aliases: ['Overhead Press', 'OHP', 'Military Press', 'Strict Press'], cues: 'Squeeze glutes, ribs down. Press through, head comes forward at lockout.' },
	'Dumbbell Shoulder Press': { priority: 92, aliases: ['DB Shoulder Press', 'Seated DB Press'], cues: 'Elbows slightly forward of shoulders. Press to full lockout without shrugging.' },
	'Standing Military Press': { priority: 90, aliases: [], cues: 'Brace like a heavy carry. Bar travels straight; move your face out of the way.' },
	'Barbell Squat': { priority: 100, aliases: ['Back Squat', 'Squat'], cues: 'Big brace before every rep. Sit down between the hips. Drive the floor apart.' },
	'Front Barbell Squat': { priority: 88, aliases: ['Front Squat'], cues: 'Elbows high, upper back fights the whole time. Stay tall, ride the bounce carefully.' },
	'Goblet Squat': { priority: 80, aliases: [], cues: 'Bell tight to chest. Elbows track inside the knees at depth.' },
	'Leg Press': { priority: 85, aliases: [], cues: 'Feet mid-platform. Lower until hips want to curl, no further. Never lock out hard.' },
	'Barbell Deadlift': { priority: 100, aliases: ['Deadlift', 'Conventional Deadlift'], cues: 'Bar over mid-foot, lats tight, wedge in. Push the floor away; hips and bar rise together.' },
	'Romanian Deadlift': { priority: 96, aliases: ['RDL', 'Romanian DL'], cues: 'Soft knees, hips straight back. Bar drags the thighs. Stop where the hamstrings stop you.' },
	'Stiff-Legged Barbell Deadlift': { priority: 84, aliases: ['SLDL'], cues: 'Hinge, do not squat it. Flat back, deep hamstring stretch.' },
	'Good Morning': { priority: 76, aliases: [], cues: 'Bar low on the traps. Hips back until the torso is near parallel. Stand by squeezing glutes.' },
	'Barbell Hip Thrust': { priority: 95, aliases: ['Hip Thrust'], cues: 'Chin tucked, ribs down. Full lockout, one-second squeeze at the top.' },
	'Bent Over Barbell Row': { priority: 95, aliases: ['Barbell Row', 'BB Row'], cues: 'Hinge to ~45°. Pull to the lower ribs, elbows tight. No heaving.' },
	'Bent Over Two-Dumbbell Row': { priority: 85, aliases: ['DB Row (two arm)'], cues: 'Flat back, pull both bells to the hips.' },
	'One-Arm Dumbbell Row': { priority: 90, aliases: ['DB Row', 'Single-Arm Row'], cues: 'Long spine, pull the elbow to the hip pocket. Let the shoulder blade move.' },
	'Seated Cable Rows': { priority: 90, aliases: ['Cable Row', 'Seated Row'], cues: 'Chest tall. Drive elbows back, squeeze the blades, slow return.' },
	'T-Bar Row with Handle': { priority: 82, aliases: ['T-Bar Row'], cues: 'Chest up, pull to the sternum, control the negative.' },
	'Pullups': { priority: 95, aliases: ['Pull-Up'], cues: 'Full hang, pull the elbows to the ribs, chin clears the bar without kipping.' },
	'Chin-Up': { priority: 90, aliases: ['Chinup'], cues: 'Supinated grip. Start from a dead hang; finish with the chest, not the chin.' },
	'Wide-Grip Lat Pulldown': { priority: 92, aliases: ['Lat Pulldown', 'Pulldown'], cues: 'Slight lean, pull to the upper chest. Elbows down and back, no swinging.' },
	'Face Pull': { priority: 88, aliases: ['Cable Face Pull'], cues: 'Pull to the bridge of the nose, thumbs back. External rotation at the end.' },
	'Side Lateral Raise': { priority: 90, aliases: ['Lateral Raise', 'DB Lateral Raise', 'Side Raise'], cues: 'Lead with the elbows, pour the pitcher. Stop at shoulder height. Lighter than you think.' },
	'Barbell Curl': { priority: 90, aliases: ['BB Curl'], cues: 'Elbows pinned to the ribs. No hip swing. Full stretch at the bottom.' },
	'Dumbbell Bicep Curl': { priority: 88, aliases: ['DB Curl', 'Biceps Curl'], cues: 'Supinate as you curl. Control down for a slow two-count.' },
	'EZ-Bar Curl': { priority: 87, aliases: ['EZ Curl'], cues: 'Comfortable grip width, elbows still, squeeze at the top.' },
	'Hammer Curls': { priority: 84, aliases: ['DB Hammer Curl'], cues: 'Neutral grip. Curl across slightly for the brachialis.' },
	'Incline Dumbbell Curl': { priority: 78, aliases: [], cues: 'Let the arms hang behind the torso — the stretch is the point.' },
	'Triceps Pushdown': { priority: 90, aliases: ['Cable Pushdown', 'Tricep Pushdown'], cues: 'Elbows glued to the ribs. Full lockout, controlled return.' },
	'Triceps Pushdown - Rope Attachment': { priority: 88, aliases: ['Rope Pushdown'], cues: 'Split the rope at the bottom, hard lockout.' },
	'Lying Triceps Press': { priority: 85, aliases: ['Skullcrusher', 'Skull Crusher', 'Lying Triceps Extension'], cues: 'Lower to the forehead or just behind. Elbows stay narrow.' },
	'Close-Grip Barbell Bench Press': { priority: 86, aliases: ['Close-Grip Bench', 'CGBP'], cues: 'Hands just inside shoulder width. Elbows tucked, bar to the lower chest.' },
	'Dips - Triceps Version': { priority: 84, aliases: ['Dips', 'Triceps Dips'], cues: 'Stay upright, elbows back. Depth to a gentle shoulder stretch.' },
	'Dumbbell Flyes': { priority: 82, aliases: ['DB Fly', 'Chest Fly'], cues: 'Soft elbows, hug a barrel. Stretch, do not sink.' },
	'Butterfly': { priority: 80, aliases: ['Pec Deck', 'Machine Fly'], cues: 'Elbows slightly below shoulders, squeeze the pads together.' },
	'Cable Crossover': { priority: 78, aliases: ['Cable Fly'], cues: 'Step forward, slight lean. Hands meet at the sternum.' },
	'Leg Extensions': { priority: 85, aliases: ['Leg Extension', 'Quad Extension'], cues: 'Full lockout with a squeeze, slow lower.' },
	'Lying Leg Curls': { priority: 85, aliases: ['Leg Curl', 'Hamstring Curl'], cues: 'Hips stay down. Curl to full contraction, three-second lower.' },
	'Seated Leg Curl': { priority: 84, aliases: [], cues: 'Lean forward slightly to lengthen the hamstrings.' },
	'Standing Calf Raises': { priority: 85, aliases: ['Calf Raise'], cues: 'Full stretch at the bottom, pause; full rise, pause. No bouncing.' },
	'Seated Calf Raise': { priority: 82, aliases: [], cues: 'Slow reps, deep stretch — the soleus likes time under tension.' },
	'Barbell Lunge': { priority: 82, aliases: ['Walking Lunge (Barbell)'], cues: 'Long step, torso tall, back knee kisses the floor.' },
	'Dumbbell Lunges': { priority: 84, aliases: ['DB Lunge'], cues: 'Step through, push the floor away with the front heel.' },
	'One Leg Barbell Squat': { priority: 74, aliases: ['Bulgarian Split Squat (Barbell)'], cues: 'Rear foot elevated. Most of the weight on the front leg.' },
	'Barbell Shrug': { priority: 80, aliases: ['Shrug'], cues: 'Straight up, hold a beat at the top. No rolling.' },
	'Dumbbell Shrug': { priority: 78, aliases: ['DB Shrug'], cues: 'Big range, pause at the top.' },
	'Cable Crunch': { priority: 80, aliases: ['Kneeling Cable Crunch'], cues: 'Flex the spine, elbows to knees. The abs move the weight, not the hips.' },
	'Hanging Leg Raise': { priority: 82, aliases: [], cues: 'Posterior tilt first, then raise the legs. No swinging.' },
	'Plank': { priority: 80, aliases: [], cues: 'Glutes tight, ribs down, one long line. Breathe.' },
	"Farmer's Walk": { priority: 80, aliases: ['Farmers Carry', 'Loaded Carry'], cues: 'Tall posture, crush grip, short quick steps.' },
	'Bench Press - Powerlifting': { priority: 60, aliases: ['Competition Bench'], cues: '' },
	'Barbell Full Squat': { priority: 90, aliases: ['ATG Squat', 'Deep Squat'], cues: 'Full depth. Big brace, drive the floor apart.' }
};

// ---------------------------------------------------------------------------
// Emit SQL

const esc = (s) => String(s).replace(/'/g, "''");
const slugify = (s) =>
	s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const lines = [];
lines.push('-- Generated by scripts/seed-exercises.mjs — do not edit by hand.');
// Catalog rows are upserted rather than deleted and reinserted: routines
// reference exercise ids, and both DELETE and INSERT OR REPLACE trip that
// foreign key once you have a saved routine. Aliases and the FTS index have
// no inbound references, so those are rebuilt wholesale.
lines.push('DELETE FROM exercise_alias;');
lines.push("DELETE FROM exercise_fts;");

const misses = Object.keys(OVERRIDES).filter((n) => !exercises.some((e) => e.name === n));
const seen = new Set();
let patterned = 0;

for (const e of exercises) {
	const id = e.id ? String(e.id) : slugify(e.name);
	if (seen.has(id)) continue;
	seen.add(id);

	const { measurement, progression } = classify(e);
	const ov = OVERRIDES[e.name];
	const pat = ov ? (pattern(e) ?? fallbackPattern(e)) : pattern(e);
	const prio = ov ? ov.priority : basePriority(e, pat);
	const aliases = ov?.aliases ?? [];
	const cues = ov?.cues || null;
	const unilateral = /one-arm|one-leg|single-arm|single-leg|alternat|unilateral/i.test(e.name) ? 1 : 0;
	const image = e.images?.[0] ?? null;
	if (pat) patterned++;

	const UPSERT_COLS = [
		'name', 'measurement', 'movement_pattern', 'progression', 'equipment',
		'primary_muscles', 'secondary_muscles', 'unilateral', 'mechanic',
		'level', 'priority', 'instructions', 'cues', 'image'
	];
	lines.push(
		`INSERT INTO exercise (id,${UPSERT_COLS.join(',')}) VALUES (` +
			`'${esc(id)}','${esc(e.name)}','${measurement}',` +
			(pat ? `'${pat}'` : 'NULL') +
			`,'${progression}',` +
			(e.equipment ? `'${esc(e.equipment)}'` : 'NULL') +
			`,'${esc(JSON.stringify(e.primaryMuscles))}','${esc(JSON.stringify(e.secondaryMuscles))}',${unilateral},` +
			(e.mechanic ? `'${esc(e.mechanic)}'` : 'NULL') +
			`,` +
			(e.level ? `'${esc(e.level)}'` : 'NULL') +
			`,${prio},` +
			(e.instructions?.length ? `'${esc(e.instructions.join('\n'))}'` : 'NULL') +
			`,` +
			(cues ? `'${esc(cues)}'` : 'NULL') +
			`,` +
			(image ? `'${esc(image)}'` : 'NULL') +
			`) ON CONFLICT(id) DO UPDATE SET ` +
			UPSERT_COLS.map((col) => `${col}=excluded.${col}`).join(',') +
			`;`
	);
	for (const a of aliases) {
		lines.push(`INSERT OR IGNORE INTO exercise_alias (exercise_id, alias) VALUES ('${esc(id)}','${esc(a)}');`);
	}
	lines.push(
		`INSERT INTO exercise_fts (id, name, aliases) VALUES ('${esc(id)}','${esc(e.name)}','${esc(aliases.join(' '))}');`
	);
}

// An override whose name got no pattern from the rules still deserves one —
// derive it from the override's intent by re-running rules without exclusions.
function fallbackPattern(e) {
	for (const [re, p] of PATTERN_RULES) {
		if (re.test(e.name)) return typeof p === 'function' ? p(e) : p;
	}
	return null;
}

// Default gym so the app works before any setup.
lines.push(`INSERT OR IGNORE INTO gym (id, name) VALUES ('gym-default', 'My gym');`);
for (const eq of ['barbell', 'dumbbell', 'machine', 'cable', 'body only', 'e-z curl bar', 'kettlebells']) {
	lines.push(`INSERT OR IGNORE INTO gym_equipment (gym_id, equipment_key) VALUES ('gym-default', '${eq}');`);
}
for (const d of [45, 35, 25, 10, 5, 2.5]) {
	lines.push(`INSERT OR IGNORE INTO gym_plate (gym_id, denomination_lb, pairs) VALUES ('gym-default', ${d}, 10);`);
}
lines.push(`INSERT OR IGNORE INTO gym_bar (id, gym_id, name, weight_lb, is_default) VALUES ('bar-straight-45', 'gym-default', 'Straight bar', 45, 1);`);
lines.push(`INSERT OR IGNORE INTO gym_bar (id, gym_id, name, weight_lb, is_default) VALUES ('bar-ez-25', 'gym-default', 'EZ curl bar', 25, 0);`);

writeFileSync(OUT, lines.join('\n') + '\n');

console.log(`seeded ${seen.size} exercises, ${patterned} with movement patterns -> ${OUT}`);
if (misses.length) {
	console.warn(`\nWARNING - overrides not found in dataset (fix the names):`);
	for (const m of misses) console.warn('  - ' + m);
}
